package com.jobportal;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.data.domain.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api") class ApiController {
 final UserRepository users;final RoleRepository roles;final CompanyRepository companies;final ProfileRepository profiles;final JobRepository jobs;final ApplicationRepository apps;final SavedJobRepository saved;final HistoryRepository history;final PasswordEncoder encoder;final Tokens tokens;
 ApiController(UserRepository u,RoleRepository r,CompanyRepository c,ProfileRepository p,JobRepository j,ApplicationRepository a,SavedJobRepository s,HistoryRepository h,PasswordEncoder e,Tokens t){users=u;roles=r;companies=c;profiles=p;jobs=j;apps=a;saved=s;history=h;encoder=e;tokens=t;}
 record Register(@Email @NotBlank String email,@NotBlank @Size(min=10,max=72) String password,@NotBlank @Size(max=160) String fullName,@Pattern(regexp="JOB_SEEKER|EMPLOYER") String role){} record Login(@Email @NotBlank String email,@NotBlank String password){} record UserView(Long id,String email,String fullName,List<String> roles){} record AuthResponse(String accessToken,long expiresIn,UserView user){}
 UserAccount current(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow();} UserView view(UserAccount u){return new UserView(u.id,u.email,u.fullName,u.roles.stream().map(x->x.name).toList());}
 @PostMapping("/auth/register") ResponseEntity<?> register(@Valid @RequestBody Register x){if(users.findByEmailIgnoreCase(x.email()).isPresent())throw new IllegalArgumentException("Email already registered");UserAccount u=new UserAccount();u.email=x.email().toLowerCase(Locale.ROOT);u.fullName=x.fullName();u.passwordHash=encoder.encode(x.password());String rn=x.role()==null?"JOB_SEEKER":x.role();u.roles.add(roles.findByName(rn).orElseThrow());users.save(u);if(rn.equals("JOB_SEEKER")){SeekerProfile p=new SeekerProfile();p.userId=u.id;profiles.save(p);}else{Company c=new Company();c.ownerUserId=u.id;c.name=u.fullName+" Company";companies.save(c);}return ResponseEntity.status(201).body(new AuthResponse(tokens.issue(u),tokens.ttl,view(u)));}
 @PostMapping("/auth/login") AuthResponse login(@Valid @RequestBody Login x){UserAccount u=users.findByEmailIgnoreCase(x.email()).filter(z->z.enabled&&encoder.matches(x.password(),z.passwordHash)).orElseThrow(()->new org.springframework.security.authentication.BadCredentialsException("Invalid credentials"));return new AuthResponse(tokens.issue(u),tokens.ttl,view(u));}
 @GetMapping("/auth/me") UserView me(Authentication a){return view(current(a));}
 record ProfileDto(String headline,String summary,String skills,String location){} record CompanyDto(String name,String description,String website,String location,String logoUrl,boolean verified){}
 @GetMapping("/seeker/profile") @PreAuthorize("hasRole('JOB_SEEKER')") ProfileDto profile(Authentication a){return profiles.findById(current(a).id).map(p->new ProfileDto(p.headline,p.summary,p.skills,p.location)).orElse(new ProfileDto("","","",""));}
 @PutMapping("/seeker/profile") @PreAuthorize("hasRole('JOB_SEEKER')") ProfileDto updateProfile(Authentication a,@RequestBody ProfileDto d){SeekerProfile p=profiles.findById(current(a).id).orElseGet(()->{SeekerProfile z=new SeekerProfile();z.userId=current(a).id;return z;});p.headline=d.headline();p.summary=d.summary();p.skills=d.skills();p.location=d.location();profiles.save(p);return d;}
 CompanyDto companyDto(Company c){return new CompanyDto(c.name,c.description,c.website,c.location,c.logoUrl,c.verified);} @GetMapping("/employer/company") @PreAuthorize("hasRole('EMPLOYER')") CompanyDto company(Authentication a){return companies.findByOwnerUserId(current(a).id).map(this::companyDto).orElseThrow();}
 @PutMapping("/employer/company") @PreAuthorize("hasRole('EMPLOYER')") CompanyDto updateCompany(Authentication a,@RequestBody CompanyDto d){Company c=companies.findByOwnerUserId(current(a).id).orElseThrow();c.name=d.name();c.description=d.description();c.website=d.website();c.location=d.location();c.logoUrl=d.logoUrl();return companyDto(companies.save(c));}
 record JobInput(@NotBlank @Size(max=180) String title,@NotBlank @Size(max=20000) String description,String location,@NotBlank String jobType,String category,java.math.BigDecimal salaryMin,java.math.BigDecimal salaryMax,String experienceLevel,LocalDate deadline){} record JobView(Long id,Long companyId,String company,String title,String description,String location,String jobType,String category,java.math.BigDecimal salaryMin,java.math.BigDecimal salaryMax,String experienceLevel,String status,LocalDate deadline,LocalDateTime createdAt){}
 JobView jv(Job j){return new JobView(j.id,j.companyId,companies.findById(j.companyId).map(c->c.name).orElse(""),j.title,j.description,j.location,j.jobType,j.category,j.salaryMin,j.salaryMax,j.experienceLevel,j.status,j.deadline,j.createdAt);} void fill(Job j,JobInput x){if(x.salaryMin()!=null&&x.salaryMax()!=null&&x.salaryMin().compareTo(x.salaryMax())>0)throw new IllegalArgumentException("Minimum salary exceeds maximum");if(x.deadline()!=null&&!x.deadline().isAfter(LocalDate.now()))throw new IllegalArgumentException("Deadline must be in the future");j.title=x.title();j.description=x.description().replaceAll("(?i)<script.*?>.*?</script>","");j.location=x.location();j.jobType=x.jobType();j.category=x.category();j.salaryMin=x.salaryMin();j.salaryMax=x.salaryMax();j.experienceLevel=x.experienceLevel();j.deadline=x.deadline();j.updatedAt=LocalDateTime.now();}
 @PostMapping("/employer/jobs") @PreAuthorize("hasRole('EMPLOYER')") ResponseEntity<JobView> createJob(Authentication a,@Valid @RequestBody JobInput x){Company c=companies.findByOwnerUserId(current(a).id).orElseThrow();Job j=new Job();j.companyId=c.id;fill(j,x);return ResponseEntity.status(201).body(jv(jobs.save(j)));}
 @PutMapping("/employer/jobs/{id}") @PreAuthorize("hasRole('EMPLOYER')") JobView editJob(Authentication a,@PathVariable Long id,@Valid @RequestBody JobInput x){Job j=ownJob(a,id);fill(j,x);return jv(jobs.save(j));}
 Job ownJob(Authentication a,Long id){Job j=jobs.findById(id).orElseThrow();if(!companies.findById(j.companyId).map(c->c.ownerUserId.equals(current(a).id)).orElse(false))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND);return j;}
 @DeleteMapping("/employer/jobs/{id}") @PreAuthorize("hasRole('EMPLOYER')") ResponseEntity<Void> removeJob(Authentication a,@PathVariable Long id){Job j=ownJob(a,id);j.status="REMOVED";jobs.save(j);return ResponseEntity.noContent().build();}
 @PatchMapping("/employer/jobs/{id}/status") @PreAuthorize("hasRole('EMPLOYER')") JobView changeJob(Authentication a,@PathVariable Long id,@RequestParam String status){if(!Set.of("OPEN","CLOSED","DRAFT").contains(status))throw new IllegalArgumentException("Invalid job status");Job j=ownJob(a,id);j.status=status;return jv(jobs.save(j));}
 @GetMapping("/employer/jobs") @PreAuthorize("hasRole('EMPLOYER')") Page<JobView> employerJobs(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){Long cid=companies.findByOwnerUserId(current(a).id).orElseThrow().id;return jobs.findByCompanyId(cid,PageRequest.of(page,Math.min(size,50),Sort.by("createdAt").descending())).map(this::jv);}
 @GetMapping("/jobs") Page<JobView> search(@RequestParam(required=false) String q,@RequestParam(required=false) String location,@RequestParam(required=false) String jobType,@RequestParam(required=false) String category,@RequestParam(required=false) String experienceLevel,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return jobs.search(blank(q),blank(location),blank(jobType),blank(category),blank(experienceLevel),PageRequest.of(Math.max(0,page),Math.min(50,Math.max(1,size)),Sort.by("createdAt").descending())).map(this::jv);}String blank(String s){return s==null||s.isBlank()?null:s;}
 @GetMapping("/jobs/{id}") JobView publicJob(@PathVariable Long id){Job j=jobs.findById(id).filter(x->x.status.equals("OPEN")&&(x.deadline==null||!x.deadline.isBefore(LocalDate.now()))).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND));return jv(j);}
 @PostMapping("/jobs/{id}/apply") @PreAuthorize("hasRole('JOB_SEEKER')") ResponseEntity<?> apply(Authentication a,@PathVariable Long id,@RequestBody Map<String,String> data){Job j=jobs.findById(id).orElseThrow();if(!j.status.equals("OPEN")||(j.deadline!=null&&j.deadline.isBefore(LocalDate.now())))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Job is closed");Long uid=current(a).id;if(apps.findByJobIdAndSeekerId(id,uid).isPresent())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Already applied");Application z=new Application();z.jobId=id;z.seekerId=uid;z.coverLetter=data.get("coverLetter");apps.save(z);return ResponseEntity.status(201).body(Map.of("id",z.id,"status",z.status));}
 @GetMapping("/seeker/applications") @PreAuthorize("hasRole('JOB_SEEKER')") Page<?> seekerApps(Authentication a,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return apps.findBySeekerId(current(a).id,PageRequest.of(page,Math.min(size,50))).map(x->Map.of("id",x.id,"job",jobs.findById(x.jobId).map(this::jv).orElse(null),"status",x.status,"appliedAt",x.appliedAt));}
 @PatchMapping("/seeker/applications/{id}/withdraw") @PreAuthorize("hasRole('JOB_SEEKER')") ResponseEntity<Void> withdraw(Authentication a,@PathVariable Long id){Application x=apps.findById(id).orElseThrow();if(!x.seekerId.equals(current(a).id)||!x.status.equals("SUBMITTED"))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT);x.status="WITHDRAWN";x.updatedAt=LocalDateTime.now();apps.save(x);return ResponseEntity.noContent().build();}
 @PostMapping("/jobs/{id}/save") @PreAuthorize("hasRole('JOB_SEEKER')") ResponseEntity<Void> saveJob(Authentication a,@PathVariable Long id){if(!jobs.existsById(id))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND);SavedJobId key=new SavedJobId(current(a).id,id);if(!saved.existsById(key)){SavedJob s=new SavedJob();s.id=key;saved.save(s);}return ResponseEntity.noContent().build();}
 @DeleteMapping("/jobs/{id}/save") @PreAuthorize("hasRole('JOB_SEEKER')") ResponseEntity<Void> unsave(Authentication a,@PathVariable Long id){saved.deleteById(new SavedJobId(current(a).id,id));return ResponseEntity.noContent().build();}
 @GetMapping("/seeker/saved-jobs") @PreAuthorize("hasRole('JOB_SEEKER')") Page<?> savedJobs(Authentication a,@RequestParam(defaultValue="0") int page){return saved.findByIdUserId(current(a).id,PageRequest.of(page,20)).map(x->jobs.findById(x.id.jobId).map(this::jv).orElse(null));}
 @GetMapping("/employer/jobs/{id}/applications") @PreAuthorize("hasRole('EMPLOYER')") Page<?> employerApps(Authentication a,@PathVariable Long id,@RequestParam(defaultValue="0") int page){ownJob(a,id);return apps.findByJobId(id,PageRequest.of(page,20)).map(x->Map.of("id",x.id,"seeker",users.findById(x.seekerId).map(this::view).orElse(null),"status",x.status,"appliedAt",x.appliedAt));}
 @PatchMapping("/employer/applications/{id}/status") @PreAuthorize("hasRole('EMPLOYER')") Map<String,String> appStatus(Authentication a,@PathVariable Long id,@RequestParam String status){Application x=apps.findById(id).orElseThrow();ownJob(a,x.jobId);Set<String> allowed=Map.of("SUBMITTED",Set.of("IN_REVIEW","REJECTED"),"IN_REVIEW",Set.of("SHORTLISTED","REJECTED"),"SHORTLISTED",Set.of("HIRED","REJECTED" )).getOrDefault(x.status,Set.of());if(!allowed.contains(status))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Invalid transition");ApplicationHistory h=new ApplicationHistory();h.applicationId=id;h.changedBy=current(a).id;h.oldStatus=x.status;h.newStatus=status;history.save(h);x.status=status;x.updatedAt=LocalDateTime.now();apps.save(x);return Map.of("status",status);}
 @GetMapping("/seeker/dashboard") @PreAuthorize("hasRole('JOB_SEEKER')") Map<String,Object> seekerDashboard(Authentication a){long uid=current(a).id;List<Application> all=apps.findBySeekerId(uid,Pageable.unpaged()).getContent();List<Application> recent=all.stream().sorted(Comparator.comparing((Application x)->x.appliedAt).reversed()).limit(5).toList();Map<String,Long> counts=new HashMap<>();for(String s:List.of("SUBMITTED","IN_REVIEW","SHORTLISTED","REJECTED","HIRED","WITHDRAWN"))counts.put(s,all.stream().filter(x->x.status.equals(s)).count());return Map.of("applications",all.size(),"applicationCounts",counts,"savedJobs",saved.countByIdUserId(uid),"recentApplications",recent.stream().map(x->Map.of("id",x.id,"job",jv(jobs.findById(x.jobId).orElseThrow()),"status",x.status)).toList());}
 @GetMapping("/employer/dashboard") @PreAuthorize("hasRole('EMPLOYER')") Map<String,Object> employerDashboard(Authentication a){Long cid=companies.findByOwnerUserId(current(a).id).orElseThrow().id;List<Job> js=jobs.findAll().stream().filter(x->x.companyId.equals(cid)).toList();List<Application> all=js.stream().flatMap(j->apps.findByJobId(j.id,Pageable.unpaged()).getContent().stream()).toList();Map<String,Long> counts=new HashMap<>();for(String s:List.of("SUBMITTED","IN_REVIEW","SHORTLISTED","REJECTED","HIRED","WITHDRAWN"))counts.put(s,all.stream().filter(x->x.status.equals(s)).count());List<Map<String,Object>> recent=all.stream().sorted(Comparator.comparing((Application x)->x.appliedAt).reversed()).limit(5).map(x->Map.<String,Object>of("id",x.id,"job",jv(jobs.findById(x.jobId).orElseThrow()),"status",x.status,"appliedAt",x.appliedAt)).toList();return Map.of("openJobs",js.stream().filter(x->x.status.equals("OPEN")).count(),"totalApplicants",all.size(),"applicantsByStatus",counts,"recentApplications",recent,"jobs",js.stream().map(this::jv).toList());}
 @GetMapping("/meta/filters") Map<String,Object> filters(){return Map.of("jobTypes",List.of("FULL_TIME","PART_TIME","CONTRACT","INTERNSHIP","REMOTE"),"categories",jobs.findAll().stream().map(x->x.category).filter(Objects::nonNull).distinct().toList(),"locations",jobs.findAll().stream().map(x->x.location).filter(Objects::nonNull).distinct().toList());}
 @GetMapping("/admin/users") @PreAuthorize("hasRole('ADMIN')") Page<?> adminUsers(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return users.findAll(PageRequest.of(Math.max(0,page),Math.min(50,Math.max(1,size)),Sort.by("createdAt").descending())).map(u->Map.of("user",view(u),"enabled",u.enabled,"createdAt",u.createdAt));}
 @PatchMapping("/admin/users/{id}/enabled") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> enableUser(Authentication a,@PathVariable Long id,@RequestParam boolean enabled){UserAccount target=users.findById(id).orElseThrow();if(current(a).id.equals(id)&&!enabled)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Cannot disable yourself");target.enabled=enabled;users.save(target);return Map.of("id",id,"enabled",enabled);}
 @GetMapping("/admin/companies") @PreAuthorize("hasRole('ADMIN')") Page<?> adminCompanies(@RequestParam(defaultValue="0") int page){return companies.findAll(PageRequest.of(Math.max(0,page),50)).map(this::companyDto);}
 @PatchMapping("/admin/companies/{id}/verified") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> verifyCompany(@PathVariable Long id,@RequestParam boolean verified){Company c=companies.findById(id).orElseThrow();c.verified=verified;companies.save(c);return Map.of("id",id,"verified",verified);}
 @GetMapping("/admin/jobs") @PreAuthorize("hasRole('ADMIN')") Page<JobView> adminJobs(@RequestParam(defaultValue="0") int page){return jobs.findAll(PageRequest.of(Math.max(0,page),50)).map(this::jv);}
 @PatchMapping("/admin/jobs/{id}/moderate") @PreAuthorize("hasRole('ADMIN')") JobView moderateJob(@PathVariable Long id,@RequestParam String status){if(!Set.of("REMOVED","OPEN","CLOSED").contains(status))throw new IllegalArgumentException("Invalid moderation status");Job j=jobs.findById(id).orElseThrow();j.status=status;return jv(jobs.save(j));}
 @GetMapping("/admin/stats") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> adminStats(){Map<String,Long> jc=new HashMap<>();for(String s:List.of("DRAFT","OPEN","CLOSED","REMOVED"))jc.put(s,jobs.countByStatus(s));Map<String,Long> ac=new HashMap<>();for(String s:List.of("SUBMITTED","IN_REVIEW","SHORTLISTED","REJECTED","HIRED","WITHDRAWN"))ac.put(s,apps.countByStatus(s));return Map.of("users",users.count(),"companies",companies.count(),"jobsByStatus",jc,"applicationsByStatus",ac);}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ProblemDetail> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,e.getMessage()));}
}
